\version "2.27.2"
% automatically converted by musicxml2ly from 03b-Rhythm-Backup.xml
\pointAndClickOff

\header {
  texidoc = "Two voices with a <backup> element that does not jump to the
    beginning of the measure for voice 2 but to the second beat. Voice 1 covers
    beats 1 and 2, and voice 2 covers beats 2 and 3. There is no rest or note
    for uncovered beats."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c' {
  \clef "treble" \time 4/4 \key c \major \oneVoice c4 \voiceOne c4 }

PartPOneVoiceTwo = \relative a {
  \clef "treble" \time 4/4 \key c \major s4 a4 \oneVoice a4 }


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \voiceOne \PartPOneVoiceOne
        }
        \context Voice = "PartPOneVoiceTwo" {
          \voiceTwo \PartPOneVoiceTwo
        }
      >>
    >>
  >>
  \layout {}
